Given an unsorted array arr[] of distinct integers, construct another array countSmaller[] such that countSmaller[i] contains the count of smaller elements on the right side of each element arr[i] in the array.Examples: Input: arr[] =  [12, 1, 2, 3, 0, 11, 4]Output: [6, 1, 1, 1, 0, 1, 0]Input: arr[] = [5, 4, 3, 2, 1]Output: [4, 3, 2, 1, 0]Input: arr[] =  [1, 2, 3, 4, 5]Output: [0, 0, 0, 0, 0]Try It YourselfTable of Content[Naive Approach] Using Nested Loop - O(n*n) Time and O(n) Space[Expected  Approach] Using Merge Sort - O(nlogn) Time and O(n) Space[Naive Approach] Using Nested Loop - O(n*n) Time and O(n) SpaceThe idea is to use nested loops, where for each element we check how many elements on its right side are smaller than it.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> constructLowerArray(vector<int>& arr) {
    int n = arr.size();
    vector<int> countSmaller(n, 0);
    int i, j;

    // Check for every element how many elements on right side are smaller
    for (i = 0; i < n; i++) {
        for (j = i + 1; j < n; j++) {
            if (arr[j] < arr[i])
                countSmaller[i]++;
        }
    }
    return countSmaller;
}

// Utility function that prints out an array on a line
void printArray(vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << "\n";
}

// Driver code
int main() {
    vector<int> arr = {12, 1, 2, 3, 0, 11, 4};

    vector<int> low = constructLowerArray(arr);
    printArray(low);

    return 0;
}


