[Expected  Approach] Using Merge Sort - O(nlogn) Time and O(n) SpaceThe idea is to use a modified merge sort. We store both element values and their original indices. While merging, we count how many elements from the right half are smaller and add this count to the corresponding index’s result.Steps to solve the problem:Store each element with its index in a pair (value, index).Perform merge sort on this pair array.During merging: check if a left element is greater than a right element.If yes, then all remaining elements in the right half are smaller → add their count to the result of that left element’s index.After counting, place elements into the merged array.Otherwise, merge normally when the left element is not greater.Continue recursively until the entire array is sorted.The result array will finally hold the number of smaller elements on the right for each index.
            C++

    #include <bits/stdc++.h>
using namespace std;

void merge(vector<pair<int, int>>& v, vector<int>& ans, int l, int mid, int h) {

    // temporary array for merging both halves
    vector<pair<int, int>> t; 
    int i = l;
    int j = mid + 1;

    while (i < mid + 1 && j <= h) {

        // v[i].first is greater than 
        // all the elements from j till h.
        if (v[i].first > v[j].first) {
            ans[v[i].second] += (h - j + 1);
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
    }

    // if any elements left in left array
    while (i <= mid)
        t.push_back(v[i++]);

    // if any elements left in right array
    while (j <= h)
        t.push_back(v[j++]);

    // putting elements back in main array 
    // in descending order
    for (int k = 0, idx = l; idx <= h; idx++, k++)
        v[idx] = t[k];
}

void mergesort(vector<pair<int, int>>& v, vector<int>& ans, int i, int j) {
    if (i < j) {
        int mid = (i + j) / 2;

        // calling mergesort for left half
        mergesort(v, ans, i, mid);

        // calling mergesort for right half
        mergesort(v, ans, mid + 1, j);

        // merging both halves and generating answer
        merge(v, ans, i, mid, j);
    }
}

vector<int> constructLowerArray(vector<int>& arr) {
    int n = arr.size();

    vector<pair<int, int>> v;

    // inserting elements and corresponding index as pair
    for (int i = 0; i < n; i++)
        v.push_back({arr[i], i});

    // answer array for keeping count initialized by 0
    vector<int> ans(n, 0);

    // calling mergesort
    mergesort(v, ans, 0, n - 1);

    return ans;
}

